ROOT = pathlib.Path(__file__).resolve().parents[2]

sprite = '<svg xmlns="http://www.w3.org/2000/svg" style="display:none">' + "".join(
    f'<symbol id="i-{n}" viewBox="0 0 24 24">' + "".join(f'<path d="{d}"/>' for d in paths) + "</symbol>" for n, paths in ICONS.items()) + "</svg>"
for page in (ROOT / "app/shared/web/index.html",):
    if page.exists():
        s = page.read_text()
        s2 = re.sub(r"<!-- icons:start -->.*?<!-- icons:end -->", "<!-- icons:start -->" + sprite + "<!-- icons:end -->", s, flags=re.S)
        assert s2 != s or sprite in s, f"{page} has no <!-- icons:start --><!-- icons:end --> marker"
        page.write_text(s2)

GAMES = {"alert", "power", "stop", "pause", "backspace", "download", "settings", "clock", "play", "save", "undo", "keyboard", "users", "gamepad", "tag", "down", "close", "search", "refresh", "folder_plus", "pen", "trash", "pin", "upload", "user", "star", "folder", "eye_off", "check", "zap", "help", "music", "compass"}
TVAPPS = {"play", "download", "info", "close", "check", "clock", "eye_off"}
for app in ("android", "tvsetup", "tvhome", "tvchannels", "tvgames", "tvapps"):
    out = ROOT / "app" / app / "src/main/res/drawable"
    for n, paths in (ICONS | GAME_ICONS if app == "tvgames" else ICONS | CHANNEL_ICONS if app == "tvchannels" else ICONS).items():
        if app == "tvgames" and n not in GAMES and n not in GAME_ICONS: continue      # TV Games draws only these
        if app == "tvapps" and n not in TVAPPS: continue                            # TV Apps: its menus' icons only
        body = "".join(f'\n    <path android:pathData="{d}" android:strokeColor="#FFFFFFFF" android:strokeWidth="2" android:strokeLineCap="round" android:strokeLineJoin="round" />' for d in paths)
        (out / f"ic_{n}.xml").write_text('<?xml version="1.0" encoding="utf-8"?>\n<!-- generated by dev/gen/gen_icons.py -->\n'
            f'<vector xmlns:android="http://schemas.android.com/apk/res/android" android:width="24dp" android:height="24dp" android:viewportWidth="24" android:viewportHeight="24">{body}\n</vector>\n')
print(len(ICONS), "icons written")
